      i: ["أكمل جدول الاتساخ لمعرفة تكرار الإخراج، ثم ابدأ الجلوس على المرحاض حين يُتوقع الإخراج (مثلاً بعد الوجبات).", "فكّر بجاهزية التدريب.", "دليل على التحكم بالأمعاء: فكّر بتدريب رسمي."],
